// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, Code, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, CSS_FMT, CSS_MIN, JS_FMT, JS_MIN, SAVED } from './script'

const build: Build = ({
  tl,
  q,
  qa,
  step,
  final,
  move,
  click,
  type,
  scramble,
  count,
  wait,
  cursorOut,
}) => {
  step(0)
  move('editor', { at: 0.3, ax: 0.2, ay: 0.2 })
  click('editor')
  type('js-min', JS_MIN, { speed: 0.012 })
  scramble('lang', 'JavaScript', { at: '<0.4', duration: 0.8 })

  step(1, '+=0.4')
  move('format')
  click('format')
  tl.to(q('js-min'), { opacity: 0, filter: 'blur(6px)', duration: 0.3 }, '<')
  JS_FMT.split('\n').forEach((line, index) =>
    scramble(qa('js-scr')[index], line, {
      at: index === 0 ? '<0.1' : '<0.08',
      duration: 0.7,
      chars: '{}()=;:<>/*+-01',
    }),
  )
  tl.to(qa('js-scr'), { opacity: 0, duration: 0.2 }, '+=0.1')
  tl.to(q('js-fmt'), { opacity: 1, duration: 0.3 }, '<')
  cursorOut('<')

  step(2, '+=0.6')
  tl.to(q('js-fmt'), { opacity: 0, y: -10, duration: 0.3 })
  move('editor', { at: '<', ax: 0.3, ay: 0.2 })
  click('editor')
  type('css-min', CSS_MIN, { speed: 0.012 })
  scramble('lang', 'CSS', { at: '<0.3', duration: 0.6 })
  tl.to(q('css-min'), { opacity: 0, duration: 0.25 }, '+=0.2')
  tl.fromTo(
    qa('css-fmt-line'),
    { opacity: 0, x: -10 },
    { opacity: 1, x: 0, duration: 0.35, stagger: 0.07 },
    '<0.1',
  )

  step(3, '+=0.6')
  move('minify')
  click('minify')
  tl.to(
    qa('css-fmt-line'),
    { y: (index) => -index * 19, opacity: 0, duration: 0.45, ease: 'power3.in', stagger: 0.02 },
    '<',
  )
  tl.fromTo(
    q('css-out'),
    { opacity: 0, scaleX: 0.6 },
    { opacity: 1, scaleX: 1, duration: 0.4, ease: 'expo.out' },
    '-=0.1',
  )
  tl.fromTo(q('saved'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  count('saved-n', SAVED, { at: '<', duration: 0.6, prefix: '−', suffix: '%' })
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Formatter detecting JavaScript, formatting it, then detecting and minifying CSS"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="lang"
            className="rounded-full border border-line-strong px-2.5 py-1 font-mono text-[10px] text-[var(--accent)]"
          >
            Auto
          </span>
        }
      >
        <div className="flex h-full flex-col gap-3">
          <div
            data-d="editor"
            className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 font-mono text-[11.5px] leading-[19px]"
          >
            <p data-d="js-min" className="demo-caret absolute inset-3 break-all text-ink-soft" />
            <div className="absolute inset-3">
              {JS_FMT.split('\n').map((_, index) => (
                <p
                  key={index}
                  data-d="js-scr"
                  className="h-[19px] whitespace-pre text-[var(--accent)]"
                />
              ))}
            </div>
            <div data-d="js-fmt" className="absolute inset-0 opacity-0">
              <Code
                code={JS_FMT}
                className="rounded-none border-0 bg-transparent leading-[19px]"
                numbers={false}
              />
            </div>
            <p data-d="css-min" className="demo-caret absolute inset-3 break-all text-ink-soft" />
            <Code
              code={CSS_FMT}
              className="absolute inset-0 rounded-none border-0 bg-transparent leading-[19px]"
              numbers={false}
              name="css-fmt"
            />
            <p
              data-d="css-out"
              className="absolute inset-x-3 top-3 origin-left break-all text-emerald opacity-0"
            >
              {CSS_MIN}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Btn d="format" primary>
              Beautify
            </Btn>
            <Btn d="minify">Minify</Btn>
            <span
              data-d="saved"
              className="ml-auto rounded-full bg-emerald/15 px-2.5 py-1 font-mono text-[10px] text-emerald opacity-0"
            >
              <span data-d="saved-n">0%</span> smaller
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
